    public static final String TRAY_KEY = "theme";
    public static final List<String> IDS = Collections.unmodifiableList(Arrays.asList(OXBLOOD, GLACIER));

    private static final String[] LABELS = {"Oxblood", "Glacier"};
    private static final String[][] SPOKEN = {{"oxblood", "ox blood", "red", "the original", "default"}, {"glacier", "glacial", "blue", "ice"}};
    private static final String[][] WALLPAPERS = {{"classic", "garnet", "ember", "velvet", "dusk"}, {"glacier"}};
    private static final String[] DEFAULT_WALLPAPER = {"classic", "glacier"};
    private static final boolean[] RASTER = {false, true};
    /** hue, neutralHue, chromaCap, chromaScale, neutralScale, darkLift, lightPull, accentL; null = identity. */
    private static final double[][] DERIVE = {null, {205.0, 205.0, 0.58, 0.78, 0.9, 0.03, 0.45, 0.81}};
    private static final int[] DESTRUCTIVE = {0, 0xFFFFABAC};

    /** The index of a known theme id, or of DEFAULT. */
    static int index(String id) {
        int i = id == null ? -1 : IDS.indexOf(id);
        return i >= 0 ? i : IDS.indexOf(DEFAULT);
    }

    public static boolean known(String id) { return id != null && IDS.contains(id); }

    /** The id itself when known, otherwise DEFAULT. */
    public static String normalize(String id) { return IDS.get(index(id)); }

    public static String label(String id) { return LABELS[index(id)]; }

    /** The theme a spoken or typed name means, or null: "glacier", "Switch to Glacier" or "the original". */
    public static String fromSpoken(String words) {
        if (words == null) return null;
        String s = words.toLowerCase(java.util.Locale.ROOT).trim();
        for (int i = 0; i < IDS.size(); i++) if (s.equals(IDS.get(i))) return IDS.get(i);
        for (int i = 0; i < SPOKEN.length; i++) for (String w : SPOKEN[i]) if (s.equals(w)) return IDS.get(i);
        return null;
    }

    /** The wallpapers that belong to this theme; no other theme may draw them. */
    public static List<String> wallpapers(String id) {
        return Collections.unmodifiableList(Arrays.asList(WALLPAPERS[index(id)]));
    }

    public static String defaultWallpaper(String id) { return DEFAULT_WALLPAPER[index(id)]; }

    /** The theme a wallpaper id belongs to, or null. */
    public static String wallpaperTheme(String wallpaper) {
        for (int i = 0; i < WALLPAPERS.length; i++) for (String w : WALLPAPERS[i]) if (w.equals(wallpaper)) return IDS.get(i);
        return null;
    }

    /** Whether this theme's wallpaper is a raster image rather than procedural artwork. */
    public static boolean rasterWallpaper(String id) { return RASTER[index(id)]; }

    /**
     * This theme's colour for an Oxblood artwork colour (fields, plates, pearls, glyphs). Identity for a theme
     * without a derivation. The alpha channel is kept. Exactly the approved prototype's map, checked against it.
     */
    public static int map(String theme, int argb) {
        double[] p = DERIVE[index(theme)];
        if (p == null) return argb;
        double[] hls = hls(argb);
        double h = hls[0], l = hls[1], s = hls[2], hd = h * 360;
        boolean warm = hd >= 300 || hd <= 55;
        if (s < 0.02 || !warm) return argb;
        double s2, h2;
        if (s > 0.35 && l < 0.92) {
            s2 = Math.min(s * p[3], p[2]);
            h2 = p[0];
        } else {
            s2 = s * p[4];
            h2 = p[1];
        }
        if (l < 0.12) l = Math.min(0.12, l + p[5]);
        else if (s2 > 0.3 && l > 0.45) l = l + (p[7] - l) * p[6];
        return rgb(argb >>> 24, h2 / 360, l, s2);
    }

    /**
     * A warning, destructive or microphone-muted colour in this theme: it stays warm. A light warm foreground
     * takes the theme's destructive colour; anything else is unchanged. Identity without a derivation.
     */
    public static int warm(String theme, int argb) {
        int i = index(theme);
        if (DERIVE[i] == null) return argb;
        double[] hls = hls(argb);
        double hd = hls[0] * 360;
        if (hls[2] > 0.35 && hls[1] >= 0.6 && (hd >= 300 || hd <= 30)) return (argb & 0xFF000000) | (DESTRUCTIVE[i] & 0xFFFFFF);
        return argb;
    }

    /** Every element of colours through map(). */
    public static int[] map(String theme, int[] colours) {
        int[] out = new int[colours.length];
        for (int i = 0; i < colours.length; i++) out[i] = map(theme, colours[i]);
        return out;
    }

    // Python colorsys, line for line (the prototype's map is written with it), so results agree exactly.
    static double[] hls(int argb) {
        double r = ((argb >> 16) & 255) / 255.0, g = ((argb >> 8) & 255) / 255.0, b = (argb & 255) / 255.0;
        double maxc = Math.max(r, Math.max(g, b)), minc = Math.min(r, Math.min(g, b));
        double sumc = maxc + minc, rangec = maxc - minc, l = sumc / 2.0;
        if (minc == maxc) return new double[]{0.0, l, 0.0};
        double s = l <= 0.5 ? rangec / sumc : rangec / (2.0 - maxc - minc);
        double rc = (maxc - r) / rangec, gc = (maxc - g) / rangec, bc = (maxc - b) / rangec, h;
        if (r == maxc) h = bc - gc;
        else if (g == maxc) h = 2.0 + rc - bc;
        else h = 4.0 + gc - rc;
        return new double[]{mod1(h / 6.0), l, s};
    }

    static int rgb(int alpha, double h, double l, double s) {
        double r, g, b;
        if (s == 0.0) {
            r = g = b = l;
        } else {
            double m2 = l <= 0.5 ? l * (1.0 + s) : l + s - (l * s), m1 = 2.0 * l - m2;
            r = v(m1, m2, h + 1.0 / 3.0);
            g = v(m1, m2, h);
            b = v(m1, m2, h - 1.0 / 3.0);
        }
        return (alpha << 24) | (channel(r) << 16) | (channel(g) << 8) | channel(b);
    }

    private static double v(double m1, double m2, double hue) {
        hue = mod1(hue);
        if (hue < 1.0 / 6.0) return m1 + (m2 - m1) * hue * 6.0;
        if (hue < 0.5) return m2;
        if (hue < 2.0 / 3.0) return m1 + (m2 - m1) * (2.0 / 3.0 - hue) * 6.0;
        return m1;
    }

    /** Python's float x % 1.0 (the result takes the sign of the divisor). */
    private static double mod1(double x) {
        double m = x % 1.0;
        return m != 0 && m < 0 ? m + 1.0 : m;
    }

    /** Python's round(x * 255): ties to even. */
    private static int channel(double x) { return Math.max(0, Math.min(255, (int) Math.rint(x * 255))); }

